    $$('#idxShortcuts [data-nav]').forEach(el => el.addEventListener('click', () => navigate(el.dataset.nav)));
  }

  function roadmapItems() {
    return (window.ROADMAP?.streams || []).flatMap(stream => stream.items.map(item => ({ ...item, stream })));
