/* ==========================================================================
   VERDE v3 · índice de la app, biblioteca digerida, batch benchmark, roadmap
   Capa visual posterior a styles.css / views.css / panels.css
   ========================================================================== */

/* ---------- densidad global ---------- */
.views{padding:24px 28px 58px;max-width:1480px}
.view-head{gap:30px;margin-bottom:22px}
.view-head h1{font-size:clamp(38px,4.2vw,56px);margin:11px 0 9px}
.lead{font-size:12px;line-height:1.62;max-width:680px}
.card-head{padding:17px 19px 11px}
.section-kicker{letter-spacing:.15em}
.sim-grid{gap:12px}
.batch-card{margin-bottom:12px}

/* ---------- glow compartido ---------- */
.index-head,.idx-card,.batch-card,.road-stream,.roadmap-north-card,.lib-course-card{position:relative}
.index-head:before,.batch-card:before,.idx-card-sim:before,.idx-card-library:before,.roadmap-north-card:before{
  content:'';position:absolute;width:340px;height:240px;right:-90px;top:-120px;pointer-events:none;
  background:radial-gradient(circle,rgba(216,242,107,.13),transparent 68%);
}
.idx-card-oracle:before{content:'';position:absolute;width:220px;height:220px;right:-80px;top:-90px;pointer-events:none;background:radial-gradient(circle,rgba(185,166,230,.15),transparent 68%)}

/* ==========================================================================
   INICIO · ÍNDICE
   ========================================================================== */
.index-head{display:grid;grid-template-columns:minmax(0,1.62fr) minmax(290px,.72fr);gap:14px;margin-bottom:12px}
.index-head-copy{padding:8px 4px 10px}
.index-head h1{font:400 clamp(46px,5.2vw,76px)/.9 var(--display);letter-spacing:-.05em;margin:13px 0 15px;color:var(--cream)}
.index-head h1 em{font-style:italic;font-weight:300;color:var(--lime)}
.index-head .lead{max-width:660px}
.index-hero-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}
.index-hero-actions .btn{height:38px;font-size:10.5px}
.index-north{background:linear-gradient(155deg,rgba(216,242,107,.07),var(--panel) 62%);border:1px solid rgba(216,242,107,.16);border-radius:20px;padding:17px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 0 60px rgba(216,242,107,.05)}
.north-glow{position:absolute;width:230px;height:230px;right:-80px;top:-100px;background:radial-gradient(circle,rgba(216,242,107,.2),transparent 68%);pointer-events:none}
.index-north b{font:400 20px/1.1 var(--display);letter-spacing:-.02em;color:#eef0dd;margin:4px 0 7px}
.index-north p{font-size:10px;line-height:1.6;color:#9aa38d;margin:0 0 14px;flex:1}
.north-progress{height:4px;border-radius:4px;background:rgba(235,241,214,.08);overflow:hidden}
.north-progress i{display:block;height:100%;width:1%;background:linear-gradient(90deg,var(--lime),#8fce59);border-radius:4px;box-shadow:0 0 14px rgba(216,242,107,.6);transition:width .45s}
.north-foot{display:flex;justify-content:space-between;gap:8px;margin-top:7px;font:400 7px var(--mono);letter-spacing:.06em;color:#7f886f}
.north-foot b{color:var(--lime);font-weight:500}

.index-status{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-bottom:12px}
.is-cell{padding:11px 12px 12px;border-right:1px solid var(--line);min-width:0;position:relative}
.is-cell:last-child{border-right:0}
.is-cell>span:first-child{display:block;font:500 6.5px var(--mono);letter-spacing:.11em;text-transform:uppercase;color:#747d66;margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.is-cell>b{display:block;font:400 20px/1 var(--display);letter-spacing:-.03em;color:var(--cream);white-space:nowrap}
.is-cell>b small{font:400 7px var(--mono);color:#77806a;margin-left:3px;letter-spacing:0}
.is-tag{display:inline-block;margin-top:5px;font:400 6.5px var(--mono);letter-spacing:.05em;color:#8d977c;background:rgba(235,241,214,.05);padding:2px 5px;border-radius:4px;white-space:nowrap}
.is-tag.warn{color:#e8b56a;background:rgba(232,181,106,.1)}
.is-bar{position:absolute;left:0;right:0;bottom:0;height:2px;background:rgba(235,241,214,.05);display:block}
.is-bar i{display:block;height:100%;background:var(--lime);width:0;transition:width .4s}

.index-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
.idx-span-2{grid-column:span 2}
.idx-span-3{grid-column:span 3}
.idx-card{background:linear-gradient(160deg,#11150d,#0d110a);border:1px solid var(--line);border-radius:18px;display:flex;flex-direction:column;min-width:0;overflow:hidden;transition:.22s}
.idx-card:hover{border-color:rgba(216,242,107,.2);box-shadow:0 18px 45px rgba(0,0,0,.3)}
.idx-card-sim,.idx-card-library{background:linear-gradient(158deg,#141a10,#0d110b 68%)}
.idx-card-top{display:flex;align-items:center;gap:8px;padding:13px 15px 0;position:relative;z-index:1}
.idx-num{font:400 8px var(--mono);color:#6d765f;border:1px solid var(--line);border-radius:4px;padding:2px 4px;flex-shrink:0}
.idx-kicker{font:500 7px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:#89927a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-mini-pill{margin-left:auto;font:500 6.5px var(--mono);letter-spacing:.05em;color:#a5ae94;background:rgba(235,241,214,.06);border:1px solid var(--line);padding:3px 6px;border-radius:999px;white-space:nowrap;flex-shrink:0}
.idx-mini-pill.lime{color:#121708;background:var(--lime);border-color:transparent}
.idx-card-top .phase-pill{margin-left:auto}
.idx-card-body{padding:11px 15px 12px;position:relative;z-index:1;flex:1}
.idx-card-body h2{font:400 25px/1.02 var(--display);letter-spacing:-.03em;color:var(--cream);margin:0 0 8px}
.idx-card-body h2 em{font-style:italic;font-weight:300;color:var(--lime)}
.idx-card-body p{font-size:9.5px;line-height:1.58;color:#939c85;margin:0 0 11px}
.idx-card-body p b{color:var(--lime);font-weight:600}
.idx-card-body.compact h2{font-size:22px}
.idx-card-foot{margin-top:auto;padding:9px 15px 12px;border-top:1px solid rgba(235,241,214,.07);display:flex;align-items:center;justify-content:space-between;gap:8px;position:relative;z-index:1}
.idx-foot-meta{display:flex;align-items:center;gap:6px;font:400 6.5px var(--mono);letter-spacing:.07em;color:#77806a;min-width:0;overflow:hidden;white-space:nowrap}
.idx-foot-meta .live-dot{width:4px;height:4px;box-shadow:0 0 0 2px rgba(216,242,107,.1)}
.idx-actions{display:flex;align-items:center;gap:9px;flex-shrink:0}
.idx-actions .btn{height:29px;padding:0 11px;font-size:8.5px}
.idx-actions .text-link{font-size:8.5px}

/* sim card */
.idx-timelapse{position:relative;display:flex;gap:2px;height:36px;margin:10px 0 7px;border-radius:8px;overflow:hidden;background:rgba(8,10,6,.5);border:1px solid var(--line);padding:3px}
.idx-tl-seg{width:calc(var(--pct) * 1%);min-width:20px;position:relative;display:flex;align-items:flex-end;padding:3px 4px;border-radius:5px;background:rgba(235,241,214,.035);transition:.25s}
.idx-tl-seg span{font:500 6px var(--mono);color:#78816a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;position:relative;z-index:1}
.idx-tl-seg i{position:absolute;inset:auto 0 0 0;height:3px;background:rgba(235,241,214,.08)}
.idx-tl-seg.done{background:rgba(216,242,107,.1)}
.idx-tl-seg.done span{color:#b9cf84}
.idx-tl-seg.done i{background:rgba(216,242,107,.5)}
.idx-tl-seg.current{background:rgba(216,242,107,.16);box-shadow:inset 0 0 0 1px rgba(216,242,107,.28)}
.idx-tl-seg.current span{color:var(--lime)}
.idx-tl-seg.current i{background:var(--lime);box-shadow:0 0 10px rgba(216,242,107,.7)}
.idx-tl-playhead{position:absolute;top:2px;bottom:2px;width:2px;background:var(--lime);box-shadow:0 0 10px var(--lime);left:1%;transition:left .4s;border-radius:2px;z-index:2}
.idx-batch-readout{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:9px}
.idx-batch-readout>div{border-left:1px solid var(--line);padding-left:8px;min-width:0}
.idx-batch-readout>div:first-child{border-left:0;padding-left:0}
.idx-batch-readout span{display:block;font:400 6px var(--mono);letter-spacing:.08em;color:#737c65;margin-bottom:2px}
.idx-batch-readout b{display:block;font:600 9px var(--sans);color:#c4cdb4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-mini-herd{position:relative;height:50px;border-radius:9px;border:1px solid #28311f;background:radial-gradient(ellipse at 50% 0%,#242e1c,#10150d 76%);overflow:hidden}
.idx-mini-lamp{position:absolute;top:5px;left:22%;right:22%;height:3px;border-radius:3px;background:var(--lime);box-shadow:0 4px 20px rgba(216,242,107,.5),0 0 8px rgba(216,242,107,.7)}
.idx-mini-plants{position:absolute;inset:16px 12px 6px;display:grid;grid-template-columns:repeat(9,1fr);gap:3px;align-items:end}
.idx-pot{position:relative;height:22px;display:flex;align-items:flex-end;justify-content:center}
.idx-pot:before{content:'';position:absolute;bottom:0;width:11px;height:6px;background:linear-gradient(#87603f,#5c3d2a);clip-path:polygon(7% 0,93% 0,82% 100%,18% 100%)}
.idx-pot i{position:absolute;bottom:5px;width:2px;height:var(--h,18px);background:#8cb063;border-radius:2px}
.idx-pot i:before,.idx-pot i:after{content:'';position:absolute;width:7px;height:4px;background:#6f9b57;border-radius:100% 5% 100% 5%}
.idx-pot i:before{left:1px;top:31%;transform:rotate(18deg)}
.idx-pot i:after{left:-6px;top:55%;background:#82aa62;border-radius:5% 100% 5% 100%;transform:rotate(-18deg)}
.idx-pot.attention i{filter:sepia(.6) saturate(.7)}
.idx-pot.dead{opacity:.25}

/* course list in index */
.idx-course-list{display:flex;flex-direction:column;gap:2px;margin-bottom:9px}
.idx-course-row{display:flex;align-items:center;gap:8px;border:0;background:transparent;padding:4px 0;text-align:left;border-bottom:1px solid rgba(235,241,214,.05);border-radius:0}
.idx-course-row:last-child{border-bottom:0}
.idx-course-row:hover .idx-course-copy b{color:var(--lime)}
.idx-course-dot{width:5px;height:5px;border-radius:50%;flex-shrink:0;box-shadow:0 0 8px currentColor}
.idx-course-copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.idx-course-copy b{font:600 9.5px var(--sans);color:#c2cbb4;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-course-copy small{font:400 6.5px var(--mono);color:#727b64;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-course-bar{width:46px;height:3px;border-radius:3px;background:rgba(235,241,214,.08);overflow:hidden;flex-shrink:0}
.idx-course-bar i{display:block;height:100%;background:linear-gradient(90deg,#7fab57,var(--lime));border-radius:3px}
.idx-course-pct{width:26px;text-align:right;font:500 7px var(--mono);color:#a9b896;flex-shrink:0}
.idx-extras{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}
.idx-extra{border:1px solid var(--line);border-radius:7px;padding:5px 6px;background:rgba(8,10,6,.32);min-width:0}
.idx-extra span{display:block;font:400 6px var(--mono);letter-spacing:.06em;color:#7b846d;text-transform:uppercase}
.idx-extra b{display:block;font:400 13px var(--display);color:#cbd6b8;line-height:1.1;margin:1px 0 3px}
.idx-extra i{display:block;height:2px;border-radius:2px;background:rgba(235,241,214,.08);overflow:hidden}
.idx-extra i i{display:block;height:100%;background:#8eab63}
.idx-extra small{display:block;font:400 5.5px var(--mono);color:#6d765f;margin-top:2px;white-space:nowrap;overflow:hidden}
.idx-extra.good b{color:var(--lime)}
.idx-extra.good i i{background:var(--lime)}
.idx-extra.low b{color:var(--amber)}
.idx-extra.low i i{background:var(--amber)}

.idx-tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}
.idx-tags button{border:1px solid var(--line);background:rgba(235,241,214,.03);border-radius:999px;padding:4px 7px;font:500 7.5px var(--sans);color:#aab493;display:inline-flex;align-items:center;gap:4px}
.idx-tags button:hover{border-color:rgba(216,242,107,.3);color:var(--lime)}
.idx-tags small{font:400 6.5px var(--mono);color:#7a846c}
.idx-week-rail{display:grid;grid-template-columns:repeat(11,1fr);gap:2px;margin-top:8px}
.idx-week{height:23px;border:1px solid var(--line);background:rgba(235,241,214,.03);border-radius:4px;font:500 6.5px var(--mono);color:#7d876d;padding:0}
.idx-week.done{background:rgba(216,242,107,.1);border-color:rgba(216,242,107,.22);color:#b9cf84}
.idx-week.current{background:var(--lime);border-color:var(--lime);color:#121708;font-weight:700;box-shadow:0 0 14px rgba(216,242,107,.3)}
.idx-week:hover{border-color:rgba(216,242,107,.4)}
.idx-ask{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:8px;padding:6px 6px 6px 9px;background:rgba(8,10,6,.4);margin-top:8px}
.idx-ask span{flex:1;font-size:8px;line-height:1.4;color:#aeb8a0;font-style:italic;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.idx-ask button{width:20px;height:20px;border:0;border-radius:50%;background:var(--lime);color:#121708;font-size:10px;flex-shrink:0}
.idx-kpi{display:grid;grid-template-columns:auto 1fr;gap:2px 7px;align-items:baseline;margin-top:7px}
.idx-kpi b{font:400 22px/1 var(--display);letter-spacing:-.03em;color:var(--cream)}
.idx-kpi b:nth-of-type(2){font-size:17px;color:#b7c4a0}
.idx-kpi span{font:400 6.5px var(--mono);color:#77806a}
.idx-phase-mini{display:flex;gap:3px;margin-top:8px}
.idx-phase-mini i{flex:1;height:4px;border-radius:3px;background:rgba(235,241,214,.1)}
.idx-phase-mini i:nth-child(1){background:#8fae69}
.idx-phase-mini i:nth-child(2){background:#6b9c56}
.idx-phase-mini i:nth-child(3){background:#9aa758}
.idx-phase-mini i:nth-child(4){background:#b3a95d}
.idx-phase-mini i:nth-child(5){background:#c1a95e}
.idx-phase-mini i:nth-child(6){background:#8c9a63}
.idx-progress-line{height:3px;border-radius:3px;background:rgba(235,241,214,.08);margin-top:7px;overflow:hidden}
.idx-progress-line i{display:block;height:100%;background:var(--lime);width:0}
.idx-road-next{border:1px solid rgba(216,242,107,.14);background:rgba(216,242,107,.04);border-radius:8px;padding:7px 8px;margin-top:8px}
.idx-road-next span{display:block;font:400 6px var(--mono);letter-spacing:.09em;color:#7e886d;margin-bottom:2px}
.idx-road-next b{display:block;font:600 8.5px/1.4 var(--sans);color:#c7d4b2}
.idx-card-roadmap{background:linear-gradient(158deg,rgba(216,242,107,.055),#0d110a 62%)}

.index-foot-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-top:10px}
.idx-insights{display:flex;flex-direction:column;gap:3px}
.idx-insight-row{display:flex;align-items:center;gap:7px;border:0;border-bottom:1px solid rgba(235,241,214,.05);background:transparent;padding:5px 0;text-align:left}
.idx-insight-row:last-of-type{border-bottom:0}
.idx-insight-tag{font:600 8.5px var(--sans);color:#c6cfb8;flex:1}
.idx-insight-row>span:nth-child(2){display:flex;gap:2px}
.idx-insight-row>span:nth-child(2) i{width:4px;height:10px;border-radius:2px;display:block}
.idx-insight-row b{font:400 6.5px var(--mono);color:#7d876e}
.idx-insight-row:hover .idx-insight-tag{color:var(--lime)}
.idx-insight-more{border:0;background:none;text-align:left;color:#a8bf73;font:600 7.5px var(--sans);padding:6px 0 0}
.idx-recent{display:flex;flex-direction:column;gap:1px}
.idx-recent-row{display:flex;align-items:center;gap:7px;border:0;border-bottom:1px solid rgba(235,241,214,.05);background:transparent;padding:5px 0;text-align:left;min-width:0}
.idx-recent-row:last-child{border-bottom:0}
.idx-recent-icon{width:20px;height:23px;border:1px solid var(--line-2);border-radius:3px;display:grid;place-items:center;font:400 5px var(--mono);color:#95a282;flex-shrink:0}
.idx-recent-row>span:nth-child(2){flex:1;min-width:0}
.idx-recent-row b{display:block;font:600 8.5px var(--sans);color:#c3cdb5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-recent-row small{display:block;font:400 6.5px var(--mono);color:#727b64;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.idx-recent-row em{font:500 6px var(--mono);font-style:normal;padding:2px 4px;border-radius:3px;flex-shrink:0}
.idx-recent-row em.state-markdown{color:#121708;background:var(--lime)}
.idx-recent-row em.state-procesado{color:#e8b56a;background:rgba(232,181,106,.12)}
.idx-recent-row em.state-pendiente{color:#9aa38a;background:rgba(235,241,214,.06)}
.idx-recent-row:hover b{color:var(--lime)}
.idx-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:3px 8px}
.idx-shortcuts button{display:flex;align-items:center;justify-content:space-between;gap:6px;border:0;border-bottom:1px solid rgba(235,241,214,.05);background:transparent;padding:5px 0;font:500 8.5px var(--sans);color:#b5bfa6;text-align:left}
.idx-shortcuts button:hover{color:var(--lime)}
.idx-shortcuts em{font:400 6px var(--mono);font-style:normal;color:#6f7861;border:1px solid var(--line);border-radius:3px;padding:1px 3px}

/* ==========================================================================
   BIBLIOTECA · VISTA DIGERIDA
   ========================================================================== */
.lib-mode-tabs{display:grid;grid-template-columns:1fr 1fr auto;gap:6px;margin-bottom:12px}
.lib-mode{display:flex;align-items:center;gap:9px;border:1px solid var(--line);background:var(--panel);border-radius:11px;padding:9px 12px;text-align:left;transition:.18s}
.lib-mode:hover{border-color:var(--line-2)}
.lib-mode.active{background:rgba(216,242,107,.07);border-color:rgba(216,242,107,.28);box-shadow:inset 2px 0 var(--lime)}
.lm-ico{width:25px;height:25px;border-radius:7px;display:grid;place-items:center;background:rgba(216,242,107,.08);color:var(--lime);font-size:11px;flex-shrink:0}
.lib-mode b{display:block;font:600 10px var(--sans);color:#d3dac6}
.lib-mode small{display:block;font:400 7px var(--mono);color:#77816a;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lib-mode.active b{color:var(--lime)}
.lib-mode-ask{border:1px solid rgba(216,242,107,.16);background:rgba(216,242,107,.05);border-radius:11px;padding:0 13px;color:#bcd18a;font:600 9px var(--sans);display:flex;align-items:center;gap:6px;white-space:nowrap}
.lib-mode-ask:hover{background:rgba(216,242,107,.11);color:var(--lime)}

#libDigest,#libFiles{animation:fade .25s ease}
.digest-top{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);gap:12px;margin-bottom:12px}
.digest-copy{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:15px 18px;position:relative;overflow:hidden}
.digest-copy:after{content:'';position:absolute;width:180px;height:180px;right:-70px;bottom:-90px;background:radial-gradient(circle,rgba(216,242,107,.09),transparent 70%)}
.digest-copy h2{font:400 24px/1.05 var(--display);letter-spacing:-.03em;margin:2px 0 7px}
.digest-copy h2 em{font-style:italic;font-weight:300;color:var(--lime)}
.digest-copy p{font-size:10px;line-height:1.6;color:#929b85;margin:0;max-width:720px}
.digest-pipeline{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:12px 14px}
.pipeline-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:7px}
.pipeline-head b{font:400 19px var(--display);color:var(--lime)}
.pipeline-head b small{font:400 6.5px var(--mono);color:#7b846d;text-transform:uppercase;letter-spacing:.08em}
.pipeline-row{display:grid;grid-template-columns:132px 1fr 28px;gap:7px;align-items:center;padding:3px 0}
.pr-name{font:500 7.5px var(--sans);color:#aeb89c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pr-name small{display:none}
.pr-bar{height:3px;background:rgba(235,241,214,.08);border-radius:3px;overflow:hidden}
.pr-bar i{display:block;height:100%;background:linear-gradient(90deg,#6f9651,var(--lime));border-radius:3px}
.pipeline-row b{font:400 6.5px var(--mono);color:#8e987f;text-align:right}

.lib-course-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-bottom:12px}
.lib-course-card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:12px 13px;overflow:hidden;transition:.2s;display:flex;flex-direction:column;--cc:#6d8a5a}
.lib-course-card:before{content:'';position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--cc);opacity:.7}
.lib-course-card:hover{border-color:rgba(216,242,107,.22);transform:translateY(-2px);box-shadow:0 14px 35px rgba(0,0,0,.35)}
.lcc-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px}
.lcc-code{font:500 6.5px var(--mono);letter-spacing:.08em;color:#121708;background:var(--cc);padding:2px 5px;border-radius:3px}
.lcc-state{font:400 6px var(--mono);letter-spacing:.08em;color:#7d876e}
.lib-course-card h3{font:400 16px/1.08 var(--display);letter-spacing:-.02em;color:#e8ecdb;margin:0 0 3px}
.lcc-meta{font:400 6.5px var(--mono);color:#79826b;margin:0 0 7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lcc-progress{height:4px;border-radius:4px;background:rgba(235,241,214,.08);overflow:hidden}
.lcc-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--cc),var(--lime));border-radius:4px}
.lcc-progress-label{display:flex;justify-content:space-between;gap:6px;margin-top:3px;font:400 6.5px var(--mono);color:#7d876e}
.lcc-progress-label b{color:#b2c09a;font-weight:500}
.lcc-extras{display:grid;grid-template-columns:repeat(4,1fr);gap:3px;margin-top:7px}
.lcc-extras span{display:flex;align-items:center;justify-content:space-between;gap:3px;border:1px solid var(--line);border-radius:4px;padding:3px 4px;background:rgba(8,10,6,.28);min-width:0}
.lcc-extras i{font:400 5.5px var(--mono);font-style:normal;color:#79826b;white-space:nowrap;overflow:hidden}
.lcc-extras b{font:500 6.5px var(--mono);color:#8a947b}
.lcc-extras span.part b{color:var(--amber)}
.lcc-extras span.full b{color:var(--lime)}
.lcc-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;padding-top:7px;border-top:1px solid rgba(235,241,214,.06)}
.lcc-foot span{font:400 6px var(--mono);color:#6f7861;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lcc-foot button{border:0;background:none;color:#b5cb7f;font:600 7.5px var(--sans);padding:0;white-space:nowrap}
.lcc-foot button:hover{color:var(--lime)}

.wisdom-layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.62fr);gap:12px;align-items:start}
.wisdom-card{background:var(--panel);border:1px solid var(--line);border-radius:16px;overflow:hidden}
.wisdom-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:15px 18px 12px;border-bottom:1px solid var(--line);background:linear-gradient(160deg,rgba(216,242,107,.035),transparent 65%)}
.wisdom-head h2{font:400 22px/1.05 var(--display);letter-spacing:-.03em;margin:2px 0 5px}
.wisdom-head h2 em{font-style:italic;font-weight:300;color:var(--lime)}
.wisdom-head p{font-size:9px;line-height:1.55;color:#89927b;margin:0;max-width:640px}
.wisdom-head-side{display:flex;align-items:center;gap:6px;flex-shrink:0;padding-top:2px}
.wisdom-head-side>span:first-child{font:400 6.5px var(--mono);color:#7a836d;white-space:nowrap}
.wisdom-index{padding:4px 0}
.wisdom-course{border-bottom:1px solid var(--line);padding:0 16px 8px}
.wisdom-course:last-child{border-bottom:0}
.wc-head{display:flex;align-items:center;gap:9px;padding:10px 0 6px}
.wc-code{font:500 6.5px var(--mono);color:#121708;background:var(--cc);padding:3px 5px;border-radius:3px;flex-shrink:0}
.wc-head>div{flex:1;min-width:0}
.wc-head h3{font:400 17px/1.05 var(--display);letter-spacing:-.02em;margin:0 0 1px;color:#e6ebd8}
.wc-head small{font:400 6.5px var(--mono);color:#737c66}
.wc-head>b{font:400 19px var(--display);color:var(--lime);letter-spacing:-.03em}
.wc-bar{height:2px;border-radius:2px;background:rgba(235,241,214,.07);overflow:hidden;margin-bottom:5px}
.wc-bar i{display:block;height:100%;background:var(--cc)}
.wisdom-module{margin-top:7px}
.wm-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:2px 0 4px;border-bottom:1px dashed rgba(235,241,214,.08)}
.wm-head span{font:500 7px var(--mono);letter-spacing:.04em;color:#8a947b;text-transform:uppercase}
.wm-head em{font:400 6px var(--mono);font-style:normal;color:#68715c;white-space:nowrap}
.wisdom-entry{display:flex;align-items:center;gap:7px;width:100%;border:0;background:transparent;padding:4px 0;text-align:left;border-bottom:1px solid rgba(235,241,214,.035);min-width:0}
.wisdom-entry:last-child{border-bottom:0}
.wisdom-entry:hover .we-copy b{color:var(--lime)}
.we-dot{width:5px;height:5px;border-radius:50%;flex-shrink:0;background:#6d765f}
.we-dot.state-markdown{background:var(--lime);box-shadow:0 0 6px rgba(216,242,107,.5)}
.we-dot.state-procesado{background:var(--amber)}
.we-dot.state-pendiente{background:#4b5441}
.we-copy{flex:1;min-width:0}
.we-copy b{display:block;font:600 8.5px var(--sans);color:#c0c9b2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.we-copy small{display:block;font:400 5.8px var(--mono);color:#6b745e;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px}
.we-pct{flex-shrink:0;font:500 6px var(--mono);padding:2px 4px;border-radius:3px;background:rgba(235,241,214,.05);color:#83906f}
.we-pct.markdown{color:#121708;background:var(--lime)}
.we-pct.procesado{color:#e8b56a;background:rgba(232,181,106,.1)}
.we-pct.pendiente{color:#7d876e}

.wisdom-side{display:flex;flex-direction:column;gap:10px;position:sticky;top:84px}
.wisdom-panel{padding:13px 14px;border-radius:16px}
.wisdom-panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:7px}
.wisdom-panel-head h3{font:400 16px/1.1 var(--display);letter-spacing:-.02em;margin:1px 0 0;color:#e7ecda}
.wisdom-links{display:flex;flex-direction:column;gap:2px;max-height:245px;overflow:auto}
.wisdom-tag{display:flex;align-items:center;justify-content:space-between;gap:7px;border:0;border-bottom:1px solid rgba(235,241,214,.05);background:transparent;padding:4px 0;text-align:left;min-width:0}
.wisdom-tag:last-child{border-bottom:0}
.wisdom-tag>span{min-width:0}
.wisdom-tag span{display:block;font:600 8.5px var(--sans);color:#bcc7ac;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wisdom-tag small{display:block;font:400 5.8px var(--mono);color:#6e7761;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wisdom-tag b{font:500 7px var(--mono);color:#8b977a;background:rgba(235,241,214,.05);padding:2px 4px;border-radius:3px;flex-shrink:0}
.wisdom-tag:hover span{color:var(--lime)}
.wisdom-insights{display:flex;flex-direction:column;gap:5px;max-height:330px;overflow:auto}
.wisdom-insight{display:block;width:100%;border:1px solid var(--line);border-radius:8px;background:rgba(8,10,6,.26);padding:7px 8px;text-align:left;transition:.18s}
.wisdom-insight:hover{border-color:rgba(216,242,107,.25);background:rgba(216,242,107,.04)}
.wi-top{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:2px}
.wi-top span{font:600 8.5px var(--sans);color:#c6d0b8}
.wi-top em{font:400 5.8px var(--mono);font-style:normal;color:#7b856d}
.wisdom-insight p{font-size:7.5px;line-height:1.45;color:#818b72;margin:0 0 4px}
.wi-courses{display:flex;align-items:center;gap:3px;flex-wrap:wrap}
.wi-courses i{font:500 5.5px var(--mono);font-style:normal;color:#121708;background:var(--cc);padding:1px 3px;border-radius:2px}
.wi-courses span{font:400 5.5px var(--mono);color:#6a735d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.wm-stat{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:3px 0;border-bottom:1px solid rgba(235,241,214,.05);font:400 7.5px var(--sans);color:#98a289}
.wm-stat b{font:500 7.5px var(--mono);color:#c1cdb0}
.wm-meta-code{margin-top:7px;border:1px solid var(--line);border-radius:6px;padding:6px 7px;background:rgba(8,10,6,.4);min-width:0}
.wm-meta-code span{display:block;font:400 5.5px var(--mono);letter-spacing:.08em;color:#6d765f;margin-bottom:2px}
.wm-meta-code code{display:block;font:400 6px/1.4 var(--mono);color:#a7bc7c;word-break:break-all}
.wm-meta-code small{display:block;font:400 5.5px var(--mono);color:#69725c;margin-top:2px}
.wm-note{display:flex;gap:5px;margin-top:7px;font-size:7px;line-height:1.45;color:#7e886f}
.wm-note span{color:var(--lime)}

/* detalle de recurso: metadata */
.rd-facts{grid-template-columns:repeat(4,1fr)}
.rd-md b{color:#a9c47a}
.rd-meta-strip{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:8px}
.rd-meta-strip span{font:400 5.8px var(--mono);color:#6d765f;border:1px solid var(--line);border-radius:4px;padding:4px 5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rd-meta-strip b{color:#a6b38f;font-weight:500;margin-left:3px}

/* ==========================================================================
   SIMULADOR · BATCH
   ========================================================================== */
.batch-card{background:linear-gradient(158deg,#141a10,#0d110b 72%);border:1px solid var(--line);border-radius:20px;padding:15px 17px 13px;overflow:hidden;box-shadow:0 0 70px rgba(216,242,107,.035)}
.batch-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:11px;position:relative;z-index:1}
.batch-head h2{font:400 24px/1.05 var(--display);letter-spacing:-.03em;margin:2px 0 0;color:var(--cream)}
.batch-head h2 em{font-style:italic;font-weight:300;color:var(--lime)}
.batch-head-actions{display:flex;gap:7px;flex-shrink:0}
.batch-head-actions .btn{height:34px;padding:0 13px;font-size:9.5px}
.tl-ico{font-size:8px;line-height:1}
#timelapseBtn.playing{border-color:rgba(216,242,107,.4);color:var(--lime);box-shadow:0 0 20px rgba(216,242,107,.1)}
.batch-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;position:relative;z-index:1}
.batch-run{background:rgba(8,10,6,.42);border:1px solid var(--line);border-radius:12px;padding:10px 11px;display:flex;flex-direction:column;min-width:0;transition:.2s;--tone:lime}
.batch-run.best{border-color:rgba(216,242,107,.36);background:linear-gradient(165deg,rgba(216,242,107,.07),rgba(8,10,6,.5));box-shadow:0 0 30px rgba(216,242,107,.07)}
.br-top{display:flex;align-items:center;gap:7px;margin-bottom:8px}
.br-rank{font-size:12px;color:#8b967a;flex-shrink:0}
.batch-run.best .br-rank{color:var(--lime)}
