.br-label b{font:600 9.5px var(--sans);color:#cdd6bf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.br-score{font:400 22px/1 var(--display);color:var(--cream);letter-spacing:-.03em;display:flex;align-items:baseline;gap:3px;flex-shrink:0}
