.batch-run.best .br-score{color:var(--lime)}
.br-bars{display:flex;flex-direction:column;gap:4px;margin-bottom:7px}
.br-bars>div{display:grid;grid-template-columns:56px 1fr 48px;gap:5px;align-items:center}
.br-bars span{font:400 6px var(--mono);letter-spacing:.04em;color:#7b856c;text-transform:uppercase;white-space:nowrap}
.br-bars i{height:3px;border-radius:3px;background:rgba(235,241,214,.08);overflow:hidden}
.br-bars i i{display:block;height:100%;background:var(--tone);border-radius:3px}
.batch-run[style*="--tone:stone"]{--tone:#9aa38b}
.batch-run[style*="--tone:amber"]{--tone:#e8b56a}
.batch-run[style*="--tone:lime"]{--tone:var(--lime)}
.br-bars b{font:500 6.5px var(--mono);color:#aab69a;text-align:right;white-space:nowrap}
.br-stats{display:flex;justify-content:space-between;gap:4px;border-top:1px solid rgba(235,241,214,.06);border-bottom:1px solid rgba(235,241,214,.06);padding:5px 0;margin-bottom:5px}
.br-stats span{font:400 5.8px var(--mono);color:#707a62;text-align:center;line-height:1.4}
.br-stats b{display:block;font:500 7.5px var(--mono);color:#b9c5a8}
.br-desc{font-size:7px;line-height:1.45;color:#7e886f;margin:0 0 6px;flex:1}
.br-use{margin-top:auto;border:1px solid var(--line);background:rgba(235,241,214,.03);border-radius:5px;color:#aabf83;font:600 7px var(--sans);padding:5px;display:flex;align-items:center;justify-content:space-between;gap:4px;transition:.18s}
.br-use:hover{border-color:rgba(216,242,107,.3);color:var(--lime);background:rgba(216,242,107,.05)}
.batch-foot{display:flex;justify-content:space-between;gap:14px;font:400 6px var(--mono);letter-spacing:.03em;color:#6c755e;margin-top:8px;flex-wrap:wrap;position:relative;z-index:1}

.timelapse-band{margin-top:10px;border-top:1px solid var(--line);padding-top:9px;position:relative;z-index:1}
.timelapse-track{position:relative;padding-bottom:13px}
.tl-phases{display:flex;gap:2px;height:26px}
.tl-phase{width:var(--w);position:relative;display:flex;flex-direction:column;justify-content:flex-end;padding:2px 4px;border-radius:4px 4px 0 0;background:rgba(235,241,214,.035);border-bottom:1px solid rgba(235,241,214,.08);min-width:0;overflow:hidden}
.tl-phase span{font:500 6px var(--mono);letter-spacing:.03em;color:#858f76;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tl-phase small{font:400 5px var(--mono);color:#626b56}
.tl-phase i{position:absolute;left:0;right:0;bottom:0;height:2px;background:rgba(216,242,107,.18)}
.tl-markers{position:relative;height:13px;margin-top:2px}
.tl-marker{position:absolute;top:0;border:0;background:none;padding:0;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:1px}
.tl-marker i{width:5px;height:5px;border-radius:50%;background:#7c866d;box-shadow:0 0 0 2px rgba(8,10,6,.8)}
.tl-marker span{font:400 4.5px var(--mono);color:#68715b;white-space:nowrap}
.tl-marker.phase i{background:#9fbb68}
.tl-marker.alert i{background:var(--amber)}
.tl-marker.harvest i,.tl-marker.end i{background:var(--lime);box-shadow:0 0 8px rgba(216,242,107,.7)}
.tl-marker:hover i{transform:scale(1.5)}
.tl-playhead{position:absolute;top:0;height:26px;width:1px;background:var(--lime);box-shadow:0 0 8px var(--lime);transition:left .3s;pointer-events:none;z-index:2}
.timelapse-events{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;max-height:140px;overflow:auto;margin-top:3px}
.tl-event{display:flex;gap:6px;border:1px solid var(--line);border-radius:6px;background:rgba(8,10,6,.28);padding:5px 6px;text-align:left;min-width:0;transition:.15s}
.tl-event:hover{border-color:rgba(216,242,107,.24);background:rgba(216,242,107,.03)}
.tl-event-day{font:500 6px var(--mono);color:#93a47b;flex-shrink:0;padding-top:1px}
.tl-event-copy{min-width:0}
.tl-event-copy b{display:block;font:600 7.5px var(--sans);color:#b9c4a9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tl-event-copy small{display:block;font-size:6.3px;line-height:1.35;color:#727c64;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tl-event.alert{border-color:rgba(232,181,106,.18)}
.tl-event.alert .tl-event-day{color:var(--amber)}
.tl-event.harvest,.tl-event.end{border-color:rgba(216,242,107,.2)}
.tl-event.harvest .tl-event-day,.tl-event.end .tl-event-day{color:var(--lime)}

