.roadmap-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.roadmap-metric{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 9px;min-width:0;display:flex;flex-direction:column;justify-content:space-between}
.roadmap-metric>span{display:block;font:400 5.8px var(--mono);letter-spacing:.04em;color:#737c66;text-transform:uppercase;line-height:1.35;min-height:15px}
.roadmap-metric b{display:block;font:400 16px/1.1 var(--display);letter-spacing:-.02em;color:#dde4cf;margin:2px 0 4px}
.roadmap-metric>i{display:block;height:2px;background:rgba(235,241,214,.08);border-radius:2px;overflow:hidden}
.roadmap-metric>i i{display:block;height:100%;background:var(--lime)}
.roadmap-metric small{display:block;font:400 5.5px var(--mono);color:#68715c;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.roadmap-horizons{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-bottom:10px}
.roadmap-horizon{position:relative;display:flex;align-items:flex-start;gap:7px;border:1px solid var(--line);background:var(--panel);border-radius:11px;padding:9px 10px;text-align:left;transition:.18s;overflow:hidden;min-width:0}
.roadmap-horizon:hover{border-color:var(--line-2)}
.roadmap-horizon.active{border-color:rgba(216,242,107,.4);background:rgba(216,242,107,.06)}
.rh-index{font:400 7px var(--mono);color:#66705a;border:1px solid var(--line);border-radius:3px;padding:1px 3px;flex-shrink:0}
.rh-copy{flex:1;min-width:0}
.rh-copy b{display:block;font:400 15px/1 var(--display);color:#dde4cf;margin-bottom:2px}
.rh-copy small{display:block;font:400 6px var(--mono);color:#7a836c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rh-copy em{display:block;font-size:6.5px;line-height:1.35;color:#6e7761;font-style:normal;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rh-pct{font:400 15px var(--display);color:var(--lime);flex-shrink:0}
.rh-bar{position:absolute;left:0;right:0;bottom:0;height:2px;background:rgba(235,241,214,.06)}
.rh-bar i{display:block;height:100%;background:var(--lime)}

.roadmap-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:8px 0}
.roadmap-legend{display:flex;gap:9px;flex-wrap:wrap}
.roadmap-legend span{display:flex;align-items:center;gap:4px;font:400 6.5px var(--mono);letter-spacing:.04em;color:#858f76}
.roadmap-legend i{width:5px;height:5px;border-radius:50%}
.rs-done{background:var(--lime);box-shadow:0 0 6px rgba(216,242,107,.6)}
.rs-now{background:var(--amber)}
.rs-next{background:#9bb8c9}
.rs-later{background:#5a6350}
.roadmap-filters{display:flex;gap:4px;flex-wrap:wrap;flex:1;justify-content:center}
.road-filter{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--line);background:transparent;border-radius:999px;padding:4px 8px;font:500 7px var(--sans);color:#9ba58b;transition:.15s}
