.road-item.next .ri-status{color:#9bb8c9}
.road-item.next .ri-status i{background:#9bb8c9}
.ri-copy{min-width:0}
.ri-copy b{display:block;font:600 8.5px/1.3 var(--sans);color:#c5cfb6;letter-spacing:-.005em}
.ri-copy p{font-size:6.5px;line-height:1.4;color:#737d65;margin:1px 0 0}
.ri-meta{grid-column:2;display:flex;gap:3px;flex-wrap:wrap;margin-top:1px}
.ri-meta span{font:400 5.2px var(--mono);letter-spacing:.02em;color:#747e66;background:rgba(235,241,214,.04);border-radius:2px;padding:1px 3px;white-space:nowrap}
.ri-meta .ri-horizon{color:#92a97c}
.ri-meta .ri-effort{color:#c2a575}
.ri-meta .ri-metric{color:#8aa0a8}
.road-item.done .ri-copy b{color:#9ba78c}
.road-empty{grid-column:1/-1;padding:13px;text-align:center;font-size:8px;color:#7a846c}

.roadmap-side{display:flex;flex-direction:column;gap:9px;position:sticky;top:82px}
.roadmap-panel{padding:12px 13px;border-radius:14px}
.roadmap-panel-head{margin-bottom:7px}
.roadmap-panel-head h3{font:400 15px/1.1 var(--display);letter-spacing:-.02em;margin:1px 0 0;color:#e2e8d5}
.roadmap-principles{display:flex;flex-direction:column;gap:5px}
.roadmap-principles>div{display:flex;gap:6px;align-items:flex-start}
.roadmap-principles span{font:400 6px var(--mono);color:var(--lime);flex-shrink:0;padding-top:1px}
.roadmap-principles p{font-size:7.3px;line-height:1.4;color:#8a947b;margin:0}
.roadmap-nongoals{display:flex;flex-direction:column;gap:4px}
.roadmap-nongoals>div{display:flex;gap:6px;align-items:flex-start}
.roadmap-nongoals span{font:500 7px var(--mono);color:var(--danger);flex-shrink:0;line-height:1.3}
.roadmap-nongoals p{font-size:7.3px;line-height:1.4;color:#8a947b;margin:0}
.roadmap-risks{display:flex;flex-direction:column;gap:5px}
.road-risk{border-bottom:1px solid rgba(235,241,214,.05);padding-bottom:5px}
