  .batch-head-actions{width:100%}
  .batch-head-actions .btn{flex:1;justify-content:center}
  .timelapse-events{grid-template-columns:1fr}
  .timelapse-events{max-height:190px}
}
@media(max-width:480px){
  .views{padding:16px 14px 86px}
  .index-status{grid-template-columns:1fr 1fr}
